#!/usr/bin/env node

import { readdirSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const packageRoot = join(dirname(fileURLToPath(import.meta.url)), "..");
const providersDir = join(packageRoot, "src/providers");

for (const file of readdirSync(providersDir)) {
	if (file.endsWith(".models.ts")) rmSync(join(providersDir, file));
}

writeFileSync(
	join(packageRoot, "src/models.generated.ts"),
	`// Generated by scripts/generate-models.ts for application-registered providers only.\n` +
		`import type { Api, ClassifierApi, ClassifierModel, ImageApi, ImageModel, Model } from "./types.ts";\n` +
		"export const MODELS: Record<string, Record<string, Model<Api>>> = {};\n" +
		"export const IMAGE_MODELS: Record<string, Record<string, ImageModel<ImageApi>>> = {};\n" +
		"export const CLASSIFIER_MODELS: Record<string, Record<string, ClassifierModel<ClassifierApi>>> = {};\n",
);
